@page "/courses"
@inject UniversityCourseCatalog.Services.CatalogService Catalog

<PageTitle>Course Catalog — Greenfield University</PageTitle>

<h1>Course Catalog</h1>

<form method="get" action="courses" class="row g-3 mb-4">
    <div class="col-md-6">
        <label for="search" class="form-label">Search</label>
        <input type="text" id="search" name="search" value="@Search" class="form-control"
               placeholder="Search by title, code, or instructor…" />
    </div>
    <div class="col-md-4">
        <label for="dept" class="form-label">Department</label>
        <select id="dept" name="dept" class="form-select">
            <option value="">All Departments</option>
            @foreach (var d in Catalog.GetDepartments())
            {
                <option value="@d.Code" selected="@(Dept == d.Code)">@d.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2 d-flex align-items-end">
        <button type="submit" class="btn btn-primary w-100">Filter</button>
    </div>
</form>

@{
    var courses = Catalog.SearchCourses(Search, Dept);
}

@if (courses.Count == 0)
{
    <div class="alert alert-info">No courses match your search criteria.</div>
}
else
{
    <p class="text-muted">Showing @courses.Count course(s)</p>
    <table class="table table-striped table-hover">
        <thead>
            <tr>
                <th>Code</th>
                <th>Title</th>
                <th>Credits</th>
                <th>Instructor</th>
                <th>Schedule</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var course in courses)
            {
                <tr>
                    <td>@course.Code</td>
                    <td>@course.Title</td>
                    <td>@course.Credits</td>
                    <td>@course.InstructorName</td>
                    <td>@course.Schedule</td>
                    <td><a href="courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [SupplyParameterFromQuery]
    public string? Search { get; set; }

    [SupplyParameterFromQuery]
    public string? Dept { get; set; }
}

@page "/departments/{Code}"
@inject UniversityCourseCatalog.Services.CatalogService Catalog

@if (department is null)
{
    <PageTitle>Department Not Found — Greenfield University</PageTitle>
    <h1>Department Not Found</h1>
    <p>The requested department does not exist.</p>
    <a href="departments" class="btn btn-outline-secondary">← Back to Departments</a>
}
else
{
    <PageTitle>@department.Name — Greenfield University</PageTitle>

    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="departments">Departments</a></li>
            <li class="breadcrumb-item active" aria-current="page">@department.Name</li>
        </ol>
    </nav>

    <h1>@department.Name <span class="badge bg-secondary">@department.Code</span></h1>
    <p class="lead">@department.Description</p>

    <h2>Courses</h2>

    @if (courses.Count == 0)
    {
        <div class="alert alert-info">No courses are currently offered in this department.</div>
    }
    else
    {
        <table class="table table-striped table-hover">
            <thead>
                <tr>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Credits</th>
                    <th>Instructor</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in courses)
                {
                    <tr>
                        <td>@course.Code</td>
                        <td>@course.Title</td>
                        <td>@course.Credits</td>
                        <td>@course.InstructorName</td>
                        <td><a href="courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                    </tr>
                }
            </tbody>
        </table>
    }
}

@code {
    [Parameter]
    public string Code { get; set; } = "";

    private UniversityCourseCatalog.Models.Department? department;
    private IReadOnlyList<UniversityCourseCatalog.Models.Course> courses = [];

    protected override void OnInitialized()
    {
        department = Catalog.GetDepartment(Code);
        if (department is not null)
        {
            courses = Catalog.GetCoursesByDepartment(Code);
        }
    }
}

@page "/enroll"
@inject UniversityCourseCatalog.Services.CatalogService Catalog

<PageTitle>Enroll — Greenfield University</PageTitle>

<h1>Enrollment Request</h1>
<p>Complete the form below to submit an enrollment request. You will receive confirmation via your university email.</p>

@if (Submitted)
{
    var selectedCourse = Catalog.GetCourse(Model.CourseId);
    <div class="alert alert-success" role="alert">
        <h4 class="alert-heading">Enrollment Request Submitted</h4>
        <p>
            Thank you, <strong>@Model.FullName</strong> (ID: @Model.StudentId).
            Your request to enroll in <strong>@selectedCourse?.Code — @selectedCourse?.Title</strong> has been received.
        </p>
        <hr />
        <p class="mb-0">You will receive a confirmation email once your enrollment is processed.</p>
    </div>
    <a href="enroll" class="btn btn-outline-primary">Submit Another Request</a>
}
else
{
    <form method="post" class="needs-validation" novalidate>
        <AntiforgeryToken />

        <div class="mb-3">
            <label for="fullName" class="form-label">Full Name</label>
            <input type="text" id="fullName" name="Model.FullName" value="@Model.FullName"
                   class="form-control" required maxlength="100" />
            @if (errors.ContainsKey(nameof(Model.FullName)))
            {
                <div class="text-danger">@errors[nameof(Model.FullName)]</div>
            }
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID</label>
            <input type="text" id="studentId" name="Model.StudentId" value="@Model.StudentId"
                   class="form-control" required pattern="[A-Za-z0-9]{6,12}"
                   placeholder="e.g., STU123456" />
            @if (errors.ContainsKey(nameof(Model.StudentId)))
            {
                <div class="text-danger">@errors[nameof(Model.StudentId)]</div>
            }
        </div>

        <div class="mb-3">
            <label for="courseId" class="form-label">Course</label>
            <select id="courseId" name="Model.CourseId" class="form-select" required>
                <option value="0">— Select a course —</option>
                @foreach (var course in Catalog.GetAllCourses())
                {
                    <option value="@course.Id" selected="@(Model.CourseId == course.Id)">
                        @course.Code — @course.Title (@course.Credits cr.)
                    </option>
                }
            </select>
            @if (errors.ContainsKey(nameof(Model.CourseId)))
            {
                <div class="text-danger">@errors[nameof(Model.CourseId)]</div>
            }
        </div>

        <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
        <a href="courses" class="btn btn-outline-secondary ms-2">Cancel</a>
    </form>
}

@code {
    [SupplyParameterFromForm]
    public UniversityCourseCatalog.Models.EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private bool Submitted { get; set; }
    private Dictionary<string, string> errors = new();

    protected override void OnInitialized()
    {
        // Pre-select course if provided via query string
        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
